values
  ('4399__AI-Agent技术开发岗__广州', '{"id":"4399__AI-Agent技术开发岗__广州","source":"builtin","basic":{"position":"AI Agent技术开发岗","company":"4399","location":"广州"},"details":{"job_url":"https://hr.4399om.com/weixin/?r=job/view&id=JO20260730001&type=agent&jobTableType=1","company_logo":null,"salaryMin":null,"salaryMax":null},"extended":{"graduation_year":"2027","recruitment_batch":"official","employment_type":"校招","job_category":"agent_dev","jd_responsibilities":["参与公司内部 AI 中台建设，基于大语言模型和 Agent 技术，将 AI 能力接入审批、即时通讯、项目管理、数据查询、报表分析等内部系统，让 AI 真正融入员工日常工作，提升公司整体协作与业务效率","参与 Agent 平台核心能力研发，包括任务规划、工具与 Skill 调用、上下文和记忆管理、工作流编排、人机确认、异常恢复、效果评测及运行监控等，与团队一起把「可以演示的 AI Demo」建设成稳定、可靠、可复用的企业级能力","与产品、业务及各信息系统研发团队深入沟通，理解真实业务流程，将复杂需求拆解为 Agent 能够理解、执行和评测的任务，让研发成果接受多部门用户和真实业务场景的检验"],"jd_requirements":["本科及以上学历，计算机、人工智能、软件工程、数学、统计等相关专业优先","编程基础扎实，熟练使用 Python，掌握常用算法和数据结构，能够编写结构清晰、可测试、可维护的工程代码","理解机器学习、深度学习和大语言模型基本原理，了解主流模型的能力边界、调用方式和应用场景","了解 RAG、Embedding、向量检索、Rerank、引用溯源等基本流程","理解 Agent 的基本工作机制，能够设计或实现包含任务规划、工具调用、状态与上下文管理、异常重试、降级处理和人工确认的多步骤工作流","具备基本的 Agent 评测意识，了解如何构造测试用例或评测集，并从任务成功率、工具调用准确率、结果正确性与一致性、事实有据性、响应延迟、Token 成本及人工接管情况等维度分析效果"],"jd_summary":"参与 4399 内部 AI 中台与 Agent 平台研发，覆盖任务规划、Skill 调用、记忆/工作流编排、人机确认、异常恢复及效果评测。将 AI 接入审批/IM/项目管理/数据查询等内部系统，把 Demo 建设为企业级可复用能力。2027 届校招，广州。","requirements_summary":"本科及以上，计算机/AI/软件/数学/统计相关专业。Python 扎实，了解 LLM 原理与 RAG/Embedding/向量检索/Rerank 流程；需能设计多步骤 Agent 工作流（规划/工具调用/重试/降级/人工确认），并具备 Agent 评测意识（成功率/准确率/Token 成本等维度）。","tech_stack":["Python","LLM","Agent","Skill","RAG","Embedding","向量检索","Rerank","工作流编排","效果评测"],"education":"本科及以上学历","major":"计算机、人工智能、软件工程、数学、统计等相关专业"},"match":{"qualified":true,"category":"agent_dev","batch_type":"official","confidence":0.99,"reason":"专精 Agent 平台研发（Skill 调用/工作流编排/人机确认/效果评测），与 OpenHarness 实践高度吻合；要求 RAG 与 Agent 工作流工程化落地，非模型训练，为当前最匹配 JD 之一"},"tier":"S"}'::jsonb, true, now()),
  ('百度__前端开发工程师__上海', '{"id":"百度__前端开发工程师__上海","source":"builtin","basic":{"position":"前端开发工程师","company":"百度","location":"上海"},"details":{"job_url":"https://talent.baidu.com/jobs/detail/GRADUATE/ff5a2fbf-b169-41cd-8a9d-56fa5b01267a?recommendCode=IZS1JH&s=2","company_logo":null,"salaryMin":null,"salaryMax":null},"extended":{"graduation_year":"","recruitment_batch":"official","employment_type":"校招","job_category":"frontend","jd_responsibilities":["负责百度各产品 Web 前端研发","百度各产品易用性改进和界面技术优化","持续优化前端性能（加载速度、渲染效率），提升用户体验","关注前端技术演进，推动工程规范与开发效率提升","探索 AI 辅助前端开发（低代码生成、智能补全）的应用"],"jd_requirements":["本科及以上学历，计算机、软件工程等相关专业优先","精通 HTML、CSS 及 JavaScript 等 Web 前端技术","具备跨浏览器、跨终端的前端开发经验","了解至少一种 Server 端语言（Node.JS/PHP/Python/Java 等）","具备扎实的计算机基础，对数据结构和算法设计有充分理解","热爱互联网，对互联网产品和技术有浓厚的兴趣，热衷于追求技术极致与创新","具有良好的沟通能力和团队合作精神、优秀的分析问题和解决问题的能力"],"jd_summary":"负责百度各产品 Web 前端研发、易用性/界面优化及性能调优，推动工程规范建设，并探索 AI 辅助前端（低代码/智能补全）。要求 HTML/CSS/JS 及跨端经验，了解 Node/Python/Java 等后端语言之一。","requirements_summary":"本科及以上计算机/软件相关专业，精通 HTML/CSS/JS，有跨浏览器/跨终端经验及算法基础。需了解 Node/PHP/Python/Java 之一；AI 为辅助前端探索方向，非 Agent/RAG 工程要求。","tech_stack":["HTML","CSS","JavaScript","Node.js","Python","Java","PHP"],"education":"本科及以上学历","major":"计算机、软件工程等相关专业"},"match":{"qualified":true,"category":"frontend","batch_type":"official","confidence":0.9,"reason":"标准 Web 前端开发岗（HTML/CSS/JS/性能优化/跨端），匹配前端开发目标；AI 仅为低代码/智能补全探索项，不如百度全栈（MCP/Skills/Agent）岗对口"},"tier":"A"}'::jsonb, true, now()),
  ('百度__全栈开发工程师__北京', '{"id":"百度__全栈开发工程师__北京","source":"builtin","basic":{"position":"全栈开发工程师","company":"百度","location":"北京"},"details":{"job_url":"https://talent.baidu.com/jobs/detail/GRADUATE/8ded98ee-9ddf-486c-96e9-75d4941d943b?recommendCode=IZS1JH&s=2","company_logo":null,"salaryMin":null,"salaryMax":null},"extended":{"graduation_year":"","recruitment_batch":"official","employment_type":"校招","job_category":"ai_fullstack","jd_responsibilities":["负责前端和服务端的业务开发工作，覆盖业务全链路，按业务需求统筹各端开发优先级，打破端侧壁垒，实现业务功能高效落地","深度运用 AI Coding 工具，开发并维护基于 MCP、CLI、Skills 等的各类工具，参与 AI 研发基础设施与 Agent 工作流建设，对接公司内部系统与模型，打造一体化 AI 研发体验","立足全栈发展趋势，推动并沉淀 Vibe Coding、SpecCoding 等新型 AI 研发范式在团队内的落地与最佳实践，参与业务全流程开发，推动业务从需求到上线的闭环落地","负责前沿技术探索与范式推广，持续跟进 AI/LLM（包含底层大模型）的最新进展，提供创新的交互解决方案，并推动技术的迭代和升级","配合团队完成技术方案讨论、架构优化、代码评审等工作，助力团队形成「按业务分工、AI+全栈协同」的开发模式，适配未来 1~2 年全栈发展导向"],"jd_requirements":["本科及以上学历，计算机、通信和电子信息科学、数学等相关专业","具备良好的计算机基础（数据结构、算法、计算机网络、操作系统等），并熟练使用至少一门编程语言","熟练使用 HTML5/CSS3/JavaScript/TypeScript/Vue/React 等前端技术完成页面布局和交互开发，有全栈开发经验者优先","熟练使用 TRAE、Claude Code、Codex、Cursor 等任一 AI Coding 工具，维护过 Rules、MCP、Skills 并了解底层机制与技术细节的同学优先","认可 AI Coder 定位，明确自身长期全栈发展规划，具备较强的学习能力和适应能力，能快速上手新领域技术，适配业务驱动的开发模式","积极乐观，责任心强，具备良好的沟通协作能力、逻辑思维能力以及服务意识"],"jd_summary":"百度校招全栈岗，覆盖前端/服务端业务全链路开发，深度参与 MCP/CLI/Skills 工具与 Agent 工作流及 AI 研发基础设施建设，推动 Vibe Coding/SpecCoding 范式落地。要求 Vue/React/TS 全栈及 Cursor 等 AI Coding 工具，维护 Rules/MCP/Skills 者优先。","requirements_summary":"本科及以上计算机/通信/数学相关专业，熟悉 Vue/React/TS 前端及全栈开发。必须熟练使用 Cursor/Claude Code 等 AI Coding 工具；维护过 Rules/MCP/Skills 并了解底层机制者优先，认可 AI Coder 定位。","tech_stack":["HTML5","CSS3","JavaScript","TypeScript","Vue","React","MCP","CLI","Skills","Agent","Cursor","Claude Code","Codex","TRAE","Vibe Coding","SpecCoding","LLM"],"education":"本科及以上学历","major":"计算机、通信和电子信息科学、数学等相关专业"},"match":{"qualified":true,"category":"ai_fullstack","batch_type":"official","confidence":0.99,"reason":"要求全栈（Vue/React/TS）+ MCP/CLI/Skills + Agent 工作流 + SpecCoding/Vibe Coding，维护 Rules/MCP/Skills 优先，与 OpenHarness/InterviewFlash 实践几乎完全对齐，为当前最匹配 JD 之一"},"tier":"S"}'::jsonb, true, now()),
